/* libc-test's functional and regression sets on Jam OS (docs/M13-PLAN.md,
 * track P2): every test of third_party/libc-test built into this one
 * program (its main renamed, the table generated by gen.py), run each as
 * a child of its own, as libc-test's runtest does, but on posix_spawn
 * (runtest forks): this program starts itself as `libc-test --one NAME`,
 * with the child's output on a pipe and a timeout, and compares what
 * happened with the expected-failures list (expected-failures.txt, each
 * line with its reason).
 *
 *   libc-test [-t SECONDS] [-v] [NAME-OR-PREFIX ...]   run them (all)
 *   libc-test -l                                       list them
 *
 * A test passes when it exits 0, as in libc-test (it returns t_status,
 * which any t_error sets). Output: PASS, FAIL (not on the list; the
 * child's first lines follow), XFAIL (on the list), XPASS (on the list
 * and passed: the list is out of date, a problem like a FAIL) and SKIP (a
 * test not built, on the list). The last lines count them; the exit
 * status is 0 when nothing is a problem. */
#include <stdbool.h>
#include <stdlib.h>
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <spawn.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>
#include "lct.h"

#define SELF        "/boot/bin/libc-test"
#define TMPDIR      "/data/lct-tmp"
#define TIMEOUT_S   20
#define KEEP        2048    /* a child's output kept for the report */
#define SHOWN_LINES 6

extern char **environ;

/* ---- the tests' side ----------------------------------------------------------------- */

/* musl's tmpfile: an unlinked file, here in $TMPDIR (set by the runner). */
FILE *lct_tmpfile(void)
{
    const char *dir = getenv("TMPDIR");
    char path[256];
    snprintf(path, sizeof(path), "%s/tmpfile_XXXXXX", dir ? dir : TMPDIR);
    int fd = mkstemp(path);
    if (fd < 0)
        return NULL;
    unlink(path);
    FILE *f = fdopen(fd, "w+");
    if (!f)
        close(fd);
    return f;
}

static const struct lct_test *find_test(const char *name)
{
    for (unsigned i = 0; i < lct_ntests; i++)
        if (!strcmp(lct_tests[i].name, name))
            return &lct_tests[i];
    return NULL;
}

/* The child: one test, argv as runtest gives it (the test's name only). */
static int run_one(const char *name)
{
    const struct lct_test *t = find_test(name);
    if (!t) {
        fprintf(stderr, "libc-test: no test %s\n", name);
        return 125;
    }
    char *argv[] = { (char *)name, NULL };
    return t->main(1, argv);
}

/* ---- the runner ---------------------------------------------------------------------- */

enum outcome { O_PASS, O_STATUS, O_SIGNAL, O_TIMEOUT, O_NOSTART };

struct result {
    enum outcome how;
    int code;               /* the exit status or the signal */
    char out[KEEP + 1];     /* what the child wrote, the first KEEP bytes */
    size_t outlen;
};

static long ms_now(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1000 + t.tv_nsec / 1000000;
}

/* Start one test and wait for it; kills it after timeout_s. */
static void run_test(const char *name, int timeout_s, struct result *r)
{
    memset(r, 0, sizeof(*r));
    int p[2];
    if (pipe2(p, O_CLOEXEC) < 0) {
        r->how = O_NOSTART;
        r->code = errno;
        return;
    }
    posix_spawn_file_actions_t fa;
    posix_spawn_file_actions_init(&fa);
    posix_spawn_file_actions_addopen(&fa, 0, "/dev/null", O_RDONLY, 0);
    posix_spawn_file_actions_adddup2(&fa, p[1], 1);
    posix_spawn_file_actions_adddup2(&fa, p[1], 2);
    char *argv[] = { "libc-test", "--one", (char *)name, NULL };
    pid_t pid;
    int e = posix_spawn(&pid, SELF, &fa, NULL, argv, environ);
    posix_spawn_file_actions_destroy(&fa);
    close(p[1]);
    if (e) {
        close(p[0]);
        r->how = O_NOSTART;
        r->code = e;
        return;
    }

    /* Read until the child's end of the pipe closes, or time is up. */
    long deadline = ms_now() + timeout_s * 1000L;
    bool timed_out = false;
    for (;;) {
        long left = deadline - ms_now();
        if (left <= 0) {
            timed_out = true;
            break;
        }
        struct pollfd pf = { .fd = p[0], .events = POLLIN };
        int n = poll(&pf, 1, left > 1000 ? 1000 : (int)left);
        if (n < 0 && errno != EINTR)
            break;
        if (n <= 0)
            continue;
        char buf[512];
        ssize_t got = read(p[0], buf, sizeof(buf));
        if (got <= 0)
            break;
        size_t room = KEEP - r->outlen;
        size_t take = (size_t)got < room ? (size_t)got : room;
        memcpy(r->out + r->outlen, buf, take);
        r->outlen += take;
    }
    close(p[0]);

    /* Its end of the output is closed, not necessarily the child: give it
     * the rest of its time, then kill it. */
    int status = 0;
    for (;;) {
        pid_t w = waitpid(pid, &status, WNOHANG);
        if (w == pid)
            break;
        if (w < 0 && errno != EINTR) {
            r->how = O_NOSTART;
            r->code = errno;
            return;
        }
        if (ms_now() >= deadline) {
            timed_out = true;
            kill(pid, SIGKILL);
            waitpid(pid, &status, 0);
            break;
        }
        usleep(2000);
    }
    if (timed_out)
        r->how = O_TIMEOUT;
    else if (WIFSIGNALED(status))
        r->how = O_SIGNAL, r->code = WTERMSIG(status);
    else if (WEXITSTATUS(status))
        r->how = O_STATUS, r->code = WEXITSTATUS(status);
}

/* Empty the tests' temporary directory: an open file cannot be unlinked
 * here, so lct_tmpfile's files stay until a test is over. */
static void clean_tmp(void)
{
    for (int pass = 0; pass < 3; pass++) {
        DIR *d = opendir(TMPDIR);
        if (!d)
            return;
        unsigned removed = 0;
        struct dirent *e;
        while ((e = readdir(d))) {
            char path[300];
            if (e->d_name[0] == '.')
                continue;
            snprintf(path, sizeof(path), "%s/%s", TMPDIR, e->d_name);
            removed += unlink(path) == 0;
        }
        closedir(d);
        if (!removed)
            return;
    }
}

static const char *expected_why(const char *name)
{
    for (unsigned i = 0; i < lct_nexpected; i++)
        if (!strcmp(lct_expected[i].name, name))
            return lct_expected[i].why;
    return NULL;
}

/* "kind" of a "kind: reason" line, as an index into kinds[]. */
static const char *const kinds[] = { "enosys", "limit", "bug", "pending", "skip" };
#define NKINDS (sizeof(kinds) / sizeof(kinds[0]))

static unsigned kind_of(const char *why)
{
    size_t l = strcspn(why, ":");
    for (unsigned i = 0; i < NKINDS; i++)
        if (strlen(kinds[i]) == l && !strncmp(why, kinds[i], l))
            return i;
    return 0;
}

static const char *describe(const struct result *r, char *buf, size_t n)
{
    switch (r->how) {
    case O_STATUS:
        snprintf(buf, n, "status %d", r->code);
        break;
    case O_SIGNAL:
        snprintf(buf, n, "signal %s", strsignal(r->code));
        break;
    case O_TIMEOUT:
        snprintf(buf, n, "timed out");
        break;
    case O_NOSTART:
        snprintf(buf, n, "not started: %s", strerror(r->code));
        break;
    default:
        snprintf(buf, n, "passed");
    }
    return buf;
}

/* The child's first lines, indented. */
static void show_output(const struct result *r)
{
    const char *p = r->out, *end = r->out + r->outlen;
    for (int line = 0; p < end && line < SHOWN_LINES; line++) {
        const char *nl = memchr(p, '\n', (size_t)(end - p));
        size_t len = nl ? (size_t)(nl - p) : (size_t)(end - p);
        printf("    | %.*s\n", (int)len, p);
        p += len + (nl != NULL);
    }
    if (p < end)
        printf("    | ...\n");
}

/* Does name belong to the arguments' selection: no argument, or it starts
 * with one of them ("functional" is a set, "functional/str" a few). */
static bool selected(const char *name, int n, char **pats)
{
    if (!n)
        return true;
    for (int i = 0; i < n; i++) {
        size_t l = strlen(pats[i]);
        if (!strncmp(name, pats[i], l))
            return true;
    }
    return false;
}

int main(int argc, char **argv)
{
    int timeout_s = TIMEOUT_S;
    bool list = false;
    int i = 1;
    for (; i < argc && argv[i][0] == '-'; i++) {
        if (!strcmp(argv[i], "--one") && i + 1 < argc)
            return run_one(argv[i + 1]);
        if (!strcmp(argv[i], "-t") && i + 1 < argc)
            timeout_s = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-l"))
            list = true;
        else {
            fprintf(stderr, "usage: libc-test [-t seconds] [-l] [name-or-prefix ...]\n");
            return 2;
        }
    }
    char **pats = argv + i;
    int npats = argc - i;
    setvbuf(stdout, NULL, _IOLBF, 0);   /* each line out as it is made */

    if (list) {
        for (unsigned t = 0; t < lct_ntests; t++)
            if (selected(lct_tests[t].name, npats, pats))
                printf("%s\n", lct_tests[t].name);
        return 0;
    }

    /* The tests' tmpfile goes to a directory of ours on /data. */
    if (mkdir(TMPDIR, 0777) < 0 && errno != EEXIST)
        printf("libc-test: no %s (%s): the tests that make temporary files will fail\n",
               TMPDIR, strerror(errno));
    clean_tmp();
    setenv("TMPDIR", TMPDIR, 1);

    unsigned run = 0, passed = 0, xfail = 0, fail = 0, xpass = 0;
    unsigned by_kind[NKINDS] = { 0 };   /* of the expected failures run; skip is never one */
    unsigned skipped = 0;
    struct result *r = malloc(sizeof(*r));
    if (!r)
        return 1;
    for (unsigned t = 0; t < lct_ntests; t++) {
        const char *name = lct_tests[t].name;
        if (!selected(name, npats, pats))
            continue;
        run++;
        run_test(name, timeout_s, r);
        clean_tmp();
        const char *why = expected_why(name);
        char how[96];
        if (r->how == O_PASS) {
            if (why) {
                xpass++;
                printf("XPASS %s: on the list (%s) but passed\n", name, why);
            } else {
                passed++;
                printf("PASS %s\n", name);
            }
        } else if (why) {
            xfail++;
            by_kind[kind_of(why)]++;
            printf("XFAIL %s [%s]: %s\n", name, describe(r, how, sizeof(how)), why);
        } else {
            fail++;
            printf("FAIL %s [%s]\n", name, describe(r, how, sizeof(how)));
            show_output(r);
        }
        fflush(stdout);
    }
    rmdir(TMPDIR);
    for (unsigned e = 0; e < lct_nexpected; e++) {
        const char *name = lct_expected[e].name;
        if (find_test(name) || !selected(name, npats, pats))
            continue;
        skipped++;
        printf("SKIP %s: %s\n", name, lct_expected[e].why);
    }

    printf("libc-test: %u run: %u passed, %u expected failures (", run, passed, xfail);
    for (unsigned k = 0; k < NKINDS - 1; k++)
        printf("%s%s %u", k ? ", " : "", kinds[k], by_kind[k]);
    printf("), %u unexpected failures, %u unexpected passes; %u not built\n", fail, xpass, skipped);
    bool ok = !fail && !xpass;
    printf("libc-test: DONE %s\n", ok ? "ok" : "with problems");
    fflush(stdout);
    return ok ? 0 : 1;
}
